import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"DA-1013 implementation plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/system-health/plan.md","filePath":"feature/admin-management/system-health/plan.md"}'),s={name:"feature/admin-management/system-health/plan.md"};function r(o,e,l,d,c,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="da-1013-implementation-plan" tabindex="-1">DA-1013 implementation plan <a class="header-anchor" href="#da-1013-implementation-plan" aria-label="Permalink to &quot;DA-1013 implementation plan&quot;">​</a></h1><p>Implement the accepted nine issues from <code>tuan-research/.scratch/brandhub-system-health/issues</code>.</p><ol><li>Business: JPA models matching monitoring SQL, bounded repositories, machine credential verification, transactional ingestion with target locks, current ADMIN authorization, safe read DTOs and clock-based freshness. Public seams: POST ingestion then GET admin, using isolated PostgreSQL and controlled time.</li><li>Gateway: exact POST machine routes without JWT filter, GET admin routes with JWT. Backend remains authoritative for machine credentials and ADMIN role. Document public paths.</li><li>Infrastructure: independent host heartbeat and probe scheduler, allowlisted configuration, read-only HTTP/Docker/database adapters, bounded response/time/concurrency, no backlog. Provision through operator tooling, not public registration. Test adapters through fixtures.</li><li>Web: lazy system-health feature, shared API service, typed snapshots, separate polling/error state, auth failures clear both snapshots. Add locales/vi/monitoring.json and locales/en/monitoring.json and register them in i18n/index.ts. Use semantic UI primitives.</li><li>Validate Maven builds/tests, worker tests, TypeScript/build and Playwright admin flow including themes/viewports. Review standards and spec separately, then commit each repo with DA-1013. Keep pre-existing unrelated edits out of commits.</li></ol><p>Existing branches are retained as requested by implement skill; baseline commits: business 7470469, gateway acd76c2, web 92d3016, infrastructure 06d1ffa. No production probes or database writes. Missing runtime/credential evidence remains explicitly unverified.</p>',4)])])}const u=t(s,[["render",r]]);export{h as __pageData,u as default};
